{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    required = ("nodes", "core_distance", "distances")
    if any(key not in case for key in required):
        raise ValueError("missing required field")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if set(core_distance) != set(nodes):
        raise ValueError("core_distance keys must exactly match nodes")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def valid_weight(value):
        return (
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(value)
            and value >= 0
        )

    for node in nodes:
        if not valid_weight(core_distance[node]):
            raise ValueError("core distances must be finite non-negative numbers")

    node_set = set(nodes)
    seen = set()
    edges = []
    for position, entry in enumerate(distances):
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance must contain two endpoints and a weight")
        left, right, distance = entry
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("distance endpoints must be distinct known nodes")
        if not valid_weight(distance):
            raise ValueError("distances must be finite non-negative numbers")
        u, v = (left, right) if left < right else (right, left)
        pair = (u, v)
        if pair in seen:
            raise ValueError("duplicate undirected distance")
        seen.add(pair)
        weight = max(core_distance[u], core_distance[v], distance)
        edges.append((weight, u, v, position))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    selected = []
    for weight, left, right, _position in edges:
        if union(left, right):
            selected.append([left, right, weight])
            if len(selected) == len(nodes) - 1:
                break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    total_weight = sum(edge[2] for edge in selected)
    return {"mst_edges": selected, "total_weight": total_weight}
